<div class="ami-panel"><div class="ami-panel-body"><h2 class="ami-section-title mb-4">Tindak Lanjut RTM</h2><p class="text-muted">Tindak lanjut hanya berasal dari keputusan RTM SPMI yang sudah resolved.</p><?php if (empty($follow_ups)): ?><div class="ami-empty"><div class="ami-empty-title">Belum ada tindak lanjut</div><div>Buka detail RTM resolved untuk membuat tindak lanjut keputusan.</div></div><?php else: ?><div class="table-responsive"><table class="table ami-table"><thead><tr><th>Kode</th><th>RTM</th><th>Keputusan</th><th>Penanggung jawab</th><th>Batas waktu</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($follow_ups as $item): ?><tr><td><?php echo html_escape($item->follow_up_code); ?></td><td><?php echo html_escape($item->meeting_code ?? '-'); ?></td><td><?php echo nl2br(html_escape($item->decision_text_snapshot)); ?></td><td><?php echo html_escape($item->responsible_name_snapshot); ?></td><td><?php echo html_escape($item->due_date ?: '-'); ?></td><td><?php echo html_escape($item->status); ?></td><td><a href="<?php echo site_url('lpmpi/spmi-follow-ups/detail/' . (int) $item->id); ?>">Detail</a><?php if ($item->status === 'open'): ?> <a href="<?php echo site_url('lpmpi/spmi-follow-ups/edit/' . (int) $item->id); ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
